import type { Landmarks, ToolResult } from '../../contracts/types';

export const MIN_VIS = 0.3;

/** Mean |ankle_y - hip_y| in normalized units: a horizontal body keeps this small. */
export function hipAnkleSpread(l: Landmarks): number {
  let sum = 0, n = 0;
  for (const f of l.frames) {
    const lm = f.landmarks;
    if (!lm || !lm[23] || !lm[27] || lm[23].visibility < MIN_VIS || lm[27].visibility < MIN_VIS) continue;
    sum += Math.abs(lm[27].y - lm[23].y); n++;
  }
  return n ? sum / n : 1;
}

export default function analyze(input: Landmarks): ToolResult {
  if (!input || !Array.isArray(input.frames) || input.frames.length === 0) {
    return { metrics: {}, warnings: ['no frames'], usable: false };
  }
  const present = input.frames.filter(f => f.landmarks).length / input.frames.length;
  const spread = hipAnkleSpread(input);
  const usable = present > 0.6 && spread < 0.5;
  return {
    metrics: { personFrameRatio: +present.toFixed(3), hipAnkleSpread: +spread.toFixed(3) },
    warnings: usable ? [] : ['finning pattern not found'],
    usable,
  };
}

