import { describe, expect, test } from 'bun:test';
import type { Landmarks } from '../../contracts/types';
import analyze, { hipAnkleSpread } from './index';

function frame(t: number, hipY: number, ankleY: number) {
  const landmarks = Array.from({ length: 33 }, () => ({ x: 0.5, y: 0.5, z: 0, visibility: 1 }));
  landmarks[23] = { x: 0.5, y: hipY, z: 0, visibility: 1 };
  landmarks[27] = { x: 0.5, y: ankleY, z: 0, visibility: 1 };
  return { t, landmarks };
}
const horizontal: Landmarks = { version: 1, source: 'synthetic', videoHash: 'h', width: 1920, height: 1080, durationSec: 1, fps: 10, frames: Array.from({ length: 10 }, (_, i) => frame(i / 10, 0.5, 0.52)) };

describe('freediving-technique', () => {
  test('known value on synthetic horizontal body', () => {
    const r = analyze(horizontal);
    expect(r.usable).toBe(true);
    expect(Math.abs(hipAnkleSpread(horizontal) - 0.02)).toBeLessThan(1e-6);
  });
  test('garbage input → usable:false', () => {
    const g: Landmarks = { ...horizontal, frames: horizontal.frames.map(f => ({ t: f.t, landmarks: null })) };
    expect(analyze(g).usable).toBe(false);
  });
  test('empty / null input does not throw', () => {
    expect(analyze(null as unknown as Landmarks).usable).toBe(false);
    expect(analyze({ frames: [] } as unknown as Landmarks).usable).toBe(false);
  });
});
